  "preview.console": { params: { sinceMs?: number; handle?: string }; result: PreviewConsoleEntry[] };
  "preview.gpuErrors": { params: { handle?: string }; result: string[] };
  "preview.status": { params: { handle?: string }; result: PreviewPortStatus };
